cells.source:
// Catalyst-side primary resource — a typed reaction network. The
// Catalyst → DiffEq comorphism's `compile_to_ode` handler parses the
// `network_source` string, derives the symbolic ODE RHS, translates
// each component into a `formulas:FormulaTerm`, and packs into an
// `OdeProblem`. Cell 5 commits that OdeProblem hand-authored, but
// the structural intent is identical: the comorphism would produce
// the same chain bytes.

namespace core     = "urn:eigenius:core";
namespace catalyst = "urn:eigenius:catalyst";
namespace nb       = "urn:eigenius:notebook:kinase_demo";

resource nb:ab_network : catalyst:ReactionNetwork {
    core:short_name              = "ab_reaction";
    catalyst:network_source      = "@reaction_network begin\n    k, A --> B\nend";
    catalyst:species_declared    = ["A", "B"];
    catalyst:parameters_declared = ["k"];
}

// Hand-author the chain-typed OdeProblem the Catalyst → DiffEq
// comorphism would produce by compiling the network in cell 4.
// `dA/dt = -k·A`, `dB/dt = k·A` — Catalyst's `compile_to_ode` handler
// emits these as App-spines over the operator catalog. Each App
// node binds exactly two children (the chain operator catalog
// declares `mul`, `add`, etc. as binary), so multi-operand
// expressions are *left-folded into nested binary apps*:
//   (-1) · A · k   becomes   `mul(mul(-1, A), k)`.
// The naïve flat shape `App(App(App(OpRef(mul), -1), A), k)` would
// be a 3-arg App-spine — the chain validator would reject it with
// `OperatorArityMismatch` against `mul`'s declared binary arity.
//
// Inductive-value literals (`App(...)`, `OpRef(...)`, `Var(...)`,
// `LitFloat(...)`) are D32 ctor calls — Phase 19f.2 added them to
// the ESL surface so FormulaTerm payloads can be authored typed +
// inline rather than via raw `eigen.load(JSON.stringify(...))` from
// a TypeScript cell. The compiler lowers each call into a chain
// `Value::Json` carrying the canonical `{ctor, args}` tagged-dict
// shape that the kernel's inductive-value validator walks against
// FormulaTerm's ctor schema at commit time.
//
// Committing the OdeSolution fires the DiffEq AutoOnLoad gate:
//   1. Decode the embedded OdeProblem via the generated mirror.
//   2. Walk each FormulaTerm RHS under `formula_to_value` to build
//      a numerical closure.
//   3. Construct an `ODEProblem(rhs!, u0, tspan, p)` and solve via
//      `Tsit5` at abstol = reltol = 1e-8.
//   4. Per-component compare `sol.u[end]` against `final_state`;
//      tolerance bound is `max(abstol, reltol·|actual|)`.
//   5. Verdict: Holds (matches), Fails (mismatch beyond tolerance),
//      Undecidable (solver hit indeterminate state).

namespace core   = "urn:eigenius:core";
namespace diffeq = "urn:eigenius:diffeq";
namespace nb     = "urn:eigenius:notebook:kinase_demo";

// `formula(...)` is the math-style infix sublanguage for inductive
// FormulaTerm values (Phase 19f.3). Standard `+ - * / ^` precedence,
// function calls map directly to the chain operator catalog at
// `urn:eigenius:formulas:ops:<name>`. Each binary App in the
// resulting tree carries exactly the operator's declared arity
// (the parser left-folds n-ary expressions into nested binary
// apps, so `(-1) * A * k` lowers to `mul(mul(-1, A), k)` not the
// 3-arg App-spine the chain validator would reject).
resource nb:rhs_A : diffeq:RhsComponent {
    diffeq:term = formula(-1 * A * k);  // dA/dt = -k·A
}

resource nb:rhs_B : diffeq:RhsComponent {
    diffeq:term = formula(A * k);       // dB/dt = k·A
}

resource nb:ode_problem : diffeq:OdeProblem {
    core:short_name           = "ab_decay";
    diffeq:state_names        = ["A", "B"];
    diffeq:parameter_names    = ["k"];
    diffeq:rhs                = [nb:rhs_A, nb:rhs_B];
    diffeq:initial_conditions = [1.0, 0.0];
    diffeq:parameters         = [1.0];
    diffeq:time_span_start    = 0.0;
    diffeq:time_span_end      = 1.0;
}

// Closed form at t=1 with k=1, A(0)=1, B(0)=0:
//   A(1) = e^-1 ≈ 0.36787944117144233
//   B(1) = 1 - e^-1 ≈ 0.6321205588285577
resource nb:ode_solution : diffeq:OdeSolution {
    core:short_name    = "ab_solution";
    diffeq:problem     = nb:ode_problem;
    diffeq:algorithm   = "Tsit5";
    diffeq:abstol      = 0.00000001;
    diffeq:reltol      = 0.00000001;
    diffeq:final_state = [0.36787944117144233, 0.6321205588285577];
}

// Query the Verdict the DiffEq AutoOnLoad gate just produced.
// `verdict_subject` points at the OdeSolution that was gated; we
// filter to it so this view shows only the verdict from cell 5.
//
// `Verdict` is declared as a `core:InductiveType` (the tri-state
// `Holds | Fails | Undecidable` ctor schema), not a `core:Class`,
// so EigenQL's `USING` clause refuses it. Use the bare-IRI MATCH
// form instead — same shape as the diffeq / catalyst demo run.sh
// scripts.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":               ?ctor,
    "urn:eigenius:institution:verdict_subject":  ?subject
}
WHERE ?subject = "urn:eigenius:notebook:kinase_demo:ode_solution"
RETURN [] {
    verdict:  ?v,
    ctor:     ?ctor,
    subject:  ?subject
}

// Symbolics → JuMP path. Author the SSE objective as a SymbolicExpression
// carrying a FormulaTerm, wrap in the SymbolicsToJuMPInput composite,
// commit the OptimisationProblem the comorphism would produce, and
// commit the OptimisesTo claim that JuMP-HiGHS will re-solve and verify.
//
// SSE = (4 - 2*Ki)^2 + (12 - 6*Ki)^2 + (22 - 11*Ki)^2.  Three
// residuals chained with `add` (left-spined). Each residual is
//   pow(sub(IC50_obs, mul(c, Ki)), 2)
// — straightforward but verbose without let-bindings; D32 ESL v1's
// inline literal form requires the SSE to appear twice (once on the
// SymbolicExpression, once on the OptimisationProblem.objective
// the comorphism would produce).

namespace core      = "urn:eigenius:core";
namespace symbolics = "urn:eigenius:symbolics";
namespace jump      = "urn:eigenius:jump";
namespace nb        = "urn:eigenius:notebook:kinase_demo";

resource nb:sse_expr : symbolics:SymbolicExpression {
    core:short_name = "ki_fit_sse";
    symbolics:term = formula((4 - 2*Ki)^2 + (12 - 6*Ki)^2 + (22 - 11*Ki)^2);
}

resource nb:ki_bound : jump:VariableBound {
    jump:variable_name = "Ki";
    jump:lower         = 0.0;
    jump:upper         = 10.0;
}

// Comorphism input — the `qc_symb_to_jump` OnDemand handler reads
// `objective.term` (identity on FormulaTerm) and forwards the rest
// of the framing fields unchanged into an OptimisationProblem.
resource nb:fit_input : symbolics:SymbolicsToJuMPInput {
    core:short_name                  = "ki_fit_input";
    symbolics:objective              = nb:sse_expr;
    symbolics:variable_names         = ["Ki"];
    symbolics:framing_variable_bounds = [nb:ki_bound];
    symbolics:sense                  = "Min";
}

// What the comorphism would produce — same SSE FormulaTerm as in
// `nb:sse_expr.term` above. (No let-bindings in ESL yet, so the
// expression is duplicated; both copies parse via the same
// `formula(...)` Pratt path.)
resource nb:opt_problem : jump:OptimisationProblem {
    core:short_name      = "ki_fit_problem";
    jump:variable_names  = ["Ki"];
    jump:variable_bounds = [nb:ki_bound];
    jump:objective       = formula((4 - 2*Ki)^2 + (12 - 6*Ki)^2 + (22 - 11*Ki)^2);
    jump:sense           = "Min";
}

resource nb:optimises_to : jump:OptimisesTo {
    core:short_name             = "ki_fit_optimum";
    jump:problem                = nb:opt_problem;
    jump:termination_status     = "OPTIMAL";
    jump:objective_value        = 0.0;
    jump:variable_values        = [2.0];
    jump:abstol                 = 0.000001;
    jump:reltol                 = 0.000001;
}

// Verdict from the JuMP-HiGHS AutoOnLoad gate. The gate rebuilt
// the OptimisationProblem under the FormulaTerm walker (smart-pow
// on, so `pow(•, 2.0)` unrolled to `(• * •)` and HiGHS saw a
// QuadExpr), called `optimize!`, and tolerance-checked the
// resolved objective against the claimed `objective_value = 0.0`.
// Holds means the institution independently reproduced Ki* = 2.0,
// SSE* = 0 within `max(abstol, reltol·|actual|) = 1e-6`.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":               ?ctor,
    "urn:eigenius:institution:verdict_subject":  ?subject
}
WHERE ?subject = "urn:eigenius:notebook:kinase_demo:optimises_to"
RETURN [] {
    verdict:  ?v,
    ctor:     ?ctor,
    subject:  ?subject
}

// All Verdicts the notebook produced. The two AutoOnLoad gates
// (DiffEq + JuMP-HiGHS) each fired once; this view aggregates both
// rows along with their gated subjects so a quick scan confirms
// every claim landed under its expected institution.

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name":                   ?ctor,
    "urn:eigenius:institution:verdict_subject":      ?subject,
    "urn:eigenius:institution:verdict_query_class":  ?qc
}
RETURN [] {
    verdict:     ?v,
    ctor:        ?ctor,
    subject:     ?subject,
    query_class: ?qc
}
ORDER BY ?ctor

cells.query:
// Donut by Verdict ctor — Holds / Fails / Undecidable distribution
// across every gate the chain has fired. After running this notebook
// fresh the donut shows 2 Holds (the DiffEq + JuMP-HiGHS gates).

MATCH "urn:eigenius:institution:Verdict"(?v) {
    "urn:eigenius:core:ctor_name": ?ctor
}
GROUP BY ?ctor
RETURN [] {
    status: ?ctor,
    count:  COUNT(?v)
}

cells.source:
// A one-line wrapper program: takes a SymbolicsToJuMPInput, calls
// the comorphism, returns the produced OptimisationProblem.
// Compiles to `Lam(input, InstitutionInvoke(symbolics_to_jump,
// input))` — the canonical D14 §9.3 dispatch surface.

namespace symbolics   = "urn:eigenius:symbolics";
namespace jump        = "urn:eigenius:jump";
namespace comorphisms = "urn:eigenius:comorphisms";
namespace nb          = "urn:eigenius:notebook:kinase_demo";

program nb:produce_problem : symbolics:SymbolicsToJuMPInput -> jump:OptimisationProblem {
    comorphisms:symbolics_to_jump(input)
}

// The comorphism just reified an OptimisationProblem and committed
// it to the chain at a deterministic content-hash IRI. The shape is
//
//   urn:eigenius:comorphism-output:symbolics_to_jump:<hex16>
//
// where the hex tail is SHA-256 over the canonical Eigon-CBOR of
// the produced resource (with @id cleared). Re-running the same
// input dedupes to the same IRI; that is the cross-fibre
// identity property the Grothendieck construction wants.

MATCH "urn:eigenius:jump:OptimisationProblem"(?p) {
    "urn:eigenius:core:short_name": ?name,
    "urn:eigenius:jump:sense":      ?sense
}
WHERE ?p LIKE "urn:eigenius:comorphism-output:symbolics_to_jump:%"
RETURN [] {
    iri:   ?p,
    name:  ?name,
    sense: ?sense
}

// EigenQL `FIBER ... INTO` — the response of an OnDemand
// QueryClass dispatch is committed to the regular chain at the
// caller-named IRI. Same `commit_with_validation` path the kernel
// uses for any chain entry, so AutoOnLoad QueryClasses bound to the
// produced class still fire.
//
// `qc_symb_to_jump` takes a SymbolicsToJuMPInput's framing fields
// directly as FIBER params (the dispatcher synthesizes the typed
// input resource on the fly). Here we re-use the same data the
// comorphism saw above; the result is structurally identical, but
// lands at the user-named IRI rather than the kernel's content-hash
// IRI.

USING INSTITUTION "urn:eigenius:institutions:symbolics" AS symb

FIBER symb:"urn:eigenius:symbolics:query_classes:qc_symb_to_jump" {
    "urn:eigenius:symbolics:objective":               "urn:eigenius:notebook:kinase_demo:sse_expr",
    "urn:eigenius:symbolics:variable_names":          ["Ki"],
    "urn:eigenius:symbolics:framing_variable_bounds": ["urn:eigenius:notebook:kinase_demo:ki_bound"],
    "urn:eigenius:symbolics:sense":                   "Min"
} AS ?problem INTO "urn:eigenius:notebook:kinase_demo:fiber_problem"
RETURN [] {
    iri: ?problem
}

// Inspect the FIBER-INTO result: it should resolve as a chain-
// resident OptimisationProblem at the user-named IRI, with the
// same JuMP-side framing the comorphism produced above.

MATCH "urn:eigenius:notebook:kinase_demo:fiber_problem"(?p) {
    "urn:eigenius:jump:sense":           ?sense,
    "urn:eigenius:jump:variable_names":  ?vars
}
RETURN [] {
    iri:   ?p,
    sense: ?sense,
    vars:  ?vars
}
